import{_ as n,a0 as o,w as p,s as g,ao as r,I as a,x as i,a1 as t,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 CentOS8/RHEL8 中配置 Rsyslog 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS8/RHEL8 中配置 Rsyslog 服务器 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS8/RHEL8 中配置 Rsyslog 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS8/RHEL8 中配置 Rsyslog 服务器 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20191018 How to Configure Rsyslog Server in CentOS 8 - RHEL 8","title":"如何在 CentOS8/RHEL8 中配置 Rsyslog 服务器","tag":"201910","desc":""},"relativePath":"201910/20191018 How to Configure Rsyslog Server in CentOS 8 - RHEL 8.md","filePath":"[post].md"}'),h={name:"201910/20191018 How to Configure Rsyslog Server in CentOS 8 - RHEL 8.md"};function d(c,s,u,k,b,y){const e=o("Link");return p(),g("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-centos8-rhel8-中配置-rsyslog-服务器" tabindex="-1">如何在 CentOS8/RHEL8 中配置 Rsyslog 服务器 <a class="header-anchor" href="#如何在-centos8-rhel8-中配置-rsyslog-服务器" aria-label="Permalink to “如何在 CentOS8/RHEL8 中配置 Rsyslog 服务器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201910/27/062908v4nnzgf7bhnplgvg.jpg" alt=""></p><p>Rsyslog 是一个自由开源的日志记录程序，在 CentOS 8 和 RHEL 8 系统上默认可用。它提供了一种从客户端节点到单个中央服务器的“集中日志”的简单有效的方法。日志集中化有两个好处。首先，它简化了日志查看，因为系统管理员可以在一个中心节点查看远程服务器的所有日志，而无需登录每个客户端系统来检查日志。如果需要监视多台服务器，这将非常有用，其次，如果远程客户端崩溃，你不用担心丢失日志，因为所有日志都将保存在中心的 Rsyslog 服务器上。rsyslog 取代了仅支持 UDP 协议的 syslog。它以优异的功能扩展了基本的 syslog 协议，例如在传输日志时支持 UDP 和 TCP 协议，增强的过滤功能以及灵活的配置选项。让我们来探讨如何在 CentOS 8 / RHEL 8 系统中配置 Rsyslog 服务器。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/configure-rsyslog-centos8-rhel8.jpg" alt="configure-rsyslog-centos8-rhel8"></p><h3 id="预先条件" tabindex="-1">预先条件 <a class="header-anchor" href="#预先条件" aria-label="Permalink to “预先条件”">​</a></h3><p>我们将搭建以下实验环境来测试集中式日志记录过程：</p><ul><li>Rsyslog 服务器       CentOS 8 Minimal    IP 地址： 10.128.0.47</li><li>客户端系统          RHEL 8 Minimal      IP 地址： 10.128.0.48</li></ul><p>通过上面的设置，我们将演示如何设置 Rsyslog 服务器，然后配置客户端系统以将日志发送到 Rsyslog 服务器进行监视。</p><p>让我们开始！</p><h3 id="在-centos-8-上配置-rsyslog-服务器" tabindex="-1">在 CentOS 8 上配置 Rsyslog 服务器 <a class="header-anchor" href="#在-centos-8-上配置-rsyslog-服务器" aria-label="Permalink to “在 CentOS 8 上配置 Rsyslog 服务器”">​</a></h3><p>默认情况下，Rsyslog 已安装在 CentOS 8 / RHEL 8 服务器上。要验证 Rsyslog 的状态，请通过 SSH 登录并运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl status rsyslog</span></span></code></pre></div><p>示例输出:</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/rsyslog-service-status-centos8.jpg" alt="rsyslog-service-status-centos8"></p><p>如果由于某种原因 Rsyslog 不存在，那么可以使用以下命令进行安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install rsyslog</span></span></code></pre></div><p>接下来，你需要修改 Rsyslog 配置文件中的一些设置。打开配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vim /etc/rsyslog.conf</span></span></code></pre></div><p>滚动并取消注释下面的行，以允许通过 UDP 协议接收日志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>module(load=&quot;imudp&quot;) # needs to be done just once</span></span>
<span class="line"><span>input(type=&quot;imudp&quot; port=&quot;514&quot;)</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/rsyslog-conf-centos8-rhel8.jpg" alt="rsyslog-conf-centos8-rhel8"></p><p>同样，如果你希望启用 TCP rsyslog 接收，请取消注释下面的行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>module(load=&quot;imtcp&quot;) # needs to be done just once</span></span>
<span class="line"><span>input(type=&quot;imtcp&quot; port=&quot;514&quot;)</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/rsyslog-conf-tcp-centos8-rhel8.jpg" alt="rsyslog-conf-tcp-centos8-rhel8"></p><p>保存并退出配置文件。</p><p>要从客户端系统接收日志，我们需要在防火墙上打开 Rsyslog 默认端口 514。为此，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sudo firewall-cmd  --add-port=514/tcp  --zone=public  --permanent</span></span></code></pre></div><p>接下来，重新加载防火墙保存更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sudo firewall-cmd --reload</span></span></code></pre></div><p>示例输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/firewall-ports-rsyslog-centos8.jpg" alt="firewall-ports-rsyslog-centos8"></p><p>接下来，重启 Rsyslog 服务器:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart rsyslog</span></span></code></pre></div><p>要在启动时运行 Rsyslog，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable rsyslog</span></span></code></pre></div><p>要确认 Rsyslog 服务器正在监听 514 端口，请使用 <code>netstat</code> 命令，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo netstat -pnltu</span></span></code></pre></div><p>示例输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/netstat-rsyslog-port-centos8.jpg" alt="netstat-rsyslog-port-centos8"></p><p>完美！我们已经成功配置了 Rsyslog 服务器来从客户端系统接收日志。</p><p>要实时查看日志消息，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail -f /var/log/messages</span></span></code></pre></div><p>现在开始配置客户端系统。</p><h3 id="在-rhel-8-上配置客户端系统" tabindex="-1">在 RHEL 8 上配置客户端系统 <a class="header-anchor" href="#在-rhel-8-上配置客户端系统" aria-label="Permalink to “在 RHEL 8 上配置客户端系统”">​</a></h3><p>与 Rsyslog 服务器一样，登录并通过以下命令检查 rsyslog 守护进程是否正在运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status rsyslog</span></span></code></pre></div><p>示例输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/client-rsyslog-service-rhel8.jpg" alt="client-rsyslog-service-rhel8"></p><p>接下来，打开 rsyslog 配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vim /etc/rsyslog.conf</span></span></code></pre></div><p>在文件末尾，添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*.* @10.128.0.47:514           # Use @ for UDP protocol</span></span>
<span class="line"><span>*.* @@10.128.0.47:514          # Use @@ for TCP protocol</span></span></code></pre></div><p>保存并退出配置文件。就像 Rsyslog 服务器一样，打开 514 端口，这是防火墙上的默认 Rsyslog 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd  --add-port=514/tcp  --zone=public  --permanent</span></span></code></pre></div><p>接下来，重新加载防火墙以保存更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --reload</span></span></code></pre></div><p>接下来，重启 rsyslog 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart rsyslog</span></span></code></pre></div><p>要在启动时运行 Rsyslog，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable rsyslog</span></span></code></pre></div><h3 id="测试日志记录操作" tabindex="-1">测试日志记录操作 <a class="header-anchor" href="#测试日志记录操作" aria-label="Permalink to “测试日志记录操作”">​</a></h3><p>已经成功安装并配置 Rsyslog 服务器和客户端后，就该验证你的配置是否按预期运行了。</p><p>在客户端系统上，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># logger &quot;Hello guys! This is our first log&quot;</span></span></code></pre></div><p>现在进入 Rsyslog 服务器并运行以下命令来实时查看日志消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tail -f /var/log/messages</span></span></code></pre></div><p>客户端系统上命令运行的输出显示在了 Rsyslog 服务器的日志中，这意味着 Rsyslog 服务器正在接收来自客户端系统的日志：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/centralize-logs-rsyslogs-centos8.jpg" alt="centralize-logs-rsyslogs-centos8"></p><p>就是这些了！我们成功设置了 Rsyslog 服务器来接收来自客户端系统的日志信息。</p><hr>`,70)),a("p",null,[s[1]||(s[1]=i("via: ",-1)),t(e,{href:"https://www.linuxtechi.com/configure-rsyslog-server-centos-8-rhel-8/"},{default:l(()=>[...s[0]||(s[0]=[i("https://www.linuxtechi.com/configure-rsyslog-server-centos-8-rhel-8/",-1)])]),_:1})]),a("p",null,[s[6]||(s[6]=i("作者：",-1)),t(e,{href:"https://www.linuxtechi.com/author/james/"},{default:l(()=>[...s[2]||(s[2]=[i("James Kiarie",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:l(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:l(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const v=n(h,[["render",d]]);export{C as __pageData,v as default};
